import React, { useState } from 'react'
import { supabase } from './supabaseClient'

function SiteForm({ position, onClose, onSiteAdded }) {
  const [name, setName] = useState('')
  const [description, setDescription] = useState('')
  const [photo, setPhoto] = useState(null)
  const [uploading, setUploading] = useState(false)

  const handleSubmit = async (e) => {
    e.preventDefault()
    setUploading(true)
    try {
      let photoUrl = null

      if (photo) {
        const ext = photo.name.split('.').pop()
        const fileName = `${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`
        const { error: uploadError } = await supabase
          .storage.from('site-photos').upload(fileName, photo, { upsert: false })
        if (uploadError) throw uploadError

        const { data } = supabase.storage.from('site-photos').getPublicUrl(fileName)
        photoUrl = data.publicUrl
      }

      const { data, error } = await supabase
        .from('derelict_sites')
        .insert([{
          name,
          description,
          latitude: position.lat,
          longitude: position.lng,
          photo_url: photoUrl
        }])
        .select()

      if (error) throw error
      onSiteAdded(data[0])
      onClose()
    } catch (err) {
      console.error(err)
      alert('Error adding site: ' + err.message)
    } finally {
      setUploading(false)
    }
  }

  return (
    <div style={{
      position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.5)',
      display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000
    }}>
      <div style={{
        background: 'white', padding: 30, borderRadius: 12, width: '90%', maxWidth: 500,
        boxShadow: '0 4px 20px rgba(0,0,0,0.3)'
      }}>
        <h2 style={{ marginTop: 0 }}>🏚️ Add Derelict Site</h2>
        <p style={{ color: '#666', fontSize: 14 }}>
          Location: {position.lat.toFixed(5)}, {position.lng.toFixed(5)}
        </p>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: 15 }}>
            <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold' }}>Site Name *</label>
            <input
              type="text" value={name} onChange={(e) => setName(e.target.value)} required
              placeholder="e.g., Abandoned Cottage"
              style={{ width: '100%', padding: 10, border: '1px solid #ccc', borderRadius: 6, fontSize: 16 }}
            />
          </div>

          <div style={{ marginBottom: 15 }}>
            <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold' }}>Description</label>
            <textarea
              value={description} onChange={(e) => setDescription(e.target.value)} rows="3"
              placeholder="Add details about this site..."
              style={{ width: '100%', padding: 10, border: '1px solid #ccc', borderRadius: 6, fontSize: 16, fontFamily: 'inherit' }}
            />
          </div>

          <div style={{ marginBottom: 20 }}>
            <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold' }}>Photo</label>
            <input type="file" accept="image/*" onChange={(e) => setPhoto(e.target.files[0])} />
          </div>

          <div style={{ display: 'flex', gap: 10 }}>
            <button type="submit" disabled={uploading}
              style={{ flex: 1, padding: 12, background: uploading ? '#ccc' : '#4CAF50', color: '#fff',
                border: 0, borderRadius: 6, fontWeight: 'bold', cursor: uploading ? 'not-allowed' : 'pointer' }}>
              {uploading ? 'Uploading...' : 'Add Site'}
            </button>
            <button type="button" onClick={onClose} disabled={uploading}
              style={{ flex: 1, padding: 12, background: '#f44336', color: '#fff',
                border: 0, borderRadius: 6, fontWeight: 'bold', cursor: uploading ? 'not-allowed' : 'pointer' }}>
              Cancel
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

export default SiteForm
